//! The benchmark corpus: types, case ids and the dispatch to the generators.
//!
//! * **S**: the specimen of Milestone 2 (own drawing, eight letters).
//! * **M**: the 26 capitals of three OFL fonts (grotesque, serif, soft
//!   display) at three sizes and four degradations.
//! * **M-hand**: the same with a handwriting OFL font.
//! * **L**: hard cases generated by code.
//! * **O**: organic and complex alphabets generated by code.
//!
//! Everything is deterministic: fixed seeds, no clock, no platform maths.

use std::collections::BTreeMap;

use kurbo::BezPath;

use crate::degrade::Degradation;
use crate::error::BenchError;
use crate::{hard_cases, render_font, specimen};

/// A corpus level.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[non_exhaustive]
pub enum Level {
    /// The specimen of Milestone 2.
    S,
    /// Three OFL alphabets.
    M,
    /// A handwriting OFL alphabet.
    MHand,
    /// Hard cases.
    L,
    /// Organic and complex alphabets.
    O,
}

impl Level {
    /// Every level, in the order of the benchmark.
    pub const ALL: [Level; 5] = [Level::S, Level::M, Level::MHand, Level::L, Level::O];

    /// The name used on the command line and in the results.
    #[must_use]
    pub fn name(self) -> &'static str {
        match self {
            Level::S => "s",
            Level::M => "m",
            Level::MHand => "m-hand",
            Level::L => "l",
            Level::O => "o",
        }
    }

    /// Parses a name (case-insensitive; `mhand` is accepted).
    #[must_use]
    pub fn parse(text: &str) -> Option<Level> {
        match text.to_ascii_lowercase().as_str() {
            "s" => Some(Level::S),
            "m" => Some(Level::M),
            "m-hand" | "mhand" => Some(Level::MHand),
            "l" => Some(Level::L),
            "o" => Some(Level::O),
            _ => None,
        }
    }
}

/// The true shape of one glyph of a case, in image pixels (y down).
#[derive(Clone, Debug)]
pub struct TruthGlyph {
    /// The union of the pieces of the glyph (contours of a non-zero fill).
    pub path: BezPath,
    /// Number of holes (enclosed background regions) of the shape.
    pub holes: usize,
    /// Bounding box in pixels: `[x0, y0, x1, y1]`.
    pub px_rect: [f64; 4],
    /// Number of separate pieces the glyph is drawn with.
    pub pieces: usize,
    /// The pen position of the glyph (`[x, baseline y]`), when it comes from a
    /// font alphabet.
    pub origin_px: Option<[f64; 2]>,
    /// The advance of the glyph in pixels, when it comes from a font.
    pub advance_px: Option<f64>,
}

/// What is known about a case.
#[derive(Clone, Debug, Default)]
pub struct Truth {
    /// Glyph shapes by character.
    pub glyphs: BTreeMap<String, TruthGlyph>,
    /// For cases with injected irregularity (level O, and `organic_wobble`):
    /// the peak displacement of the outline, in pixels.
    pub irregularity_amplitude_px: Option<f64>,
    /// Pixels per font unit, for alphabets rendered from a font.
    pub scale_px_per_unit: Option<f64>,
    /// Cap height in pixels, for alphabets rendered from a font.
    pub cap_height_px: Option<f64>,
    /// Pieces that are in the image but not in any glyph (dust, specks).
    pub stray_pieces: usize,
    /// Whether the image spreads the ink beyond the true shapes (a bleeding
    /// ink): a faithful trace follows the image, not the truth.
    pub bleeds: bool,
}

/// One image of the corpus with its layout and what is known about it.
#[derive(Clone, Debug)]
pub struct CorpusCase {
    /// Stable identifier.
    pub id: String,
    /// The level it belongs to.
    pub level: Level,
    /// The encoded image: PNG, except for the JPEG degradation, which is kept
    /// as the JPEG bytes the encoder produced.
    pub image: Vec<u8>,
    /// `"png"` or `"jpg"`.
    pub extension: &'static str,
    /// The characters of each row in reading order.
    pub layout: Vec<String>,
    /// The known truth, when there is one.
    pub truth: Option<Truth>,
}

/// The fonts of level M, in order (key, file stem).
pub(crate) const M_FONTS: [&str; 3] = ["inter", "eb-garamond", "fraunces"];
/// The font of level M-hand.
pub(crate) const HAND_FONT: &str = "patrick-hand";
/// The heights of the capitals, in pixels.
pub(crate) const M_CAPS: [u32; 3] = [60, 110, 200];

/// The ids of the L cases, in order.
pub const L_IDS: [&str; 11] = [
    "multi_piece_h",
    "slit_1px",
    "slit_2px",
    "slit_3px",
    "small_counter",
    "organic_wobble",
    "uneven_light",
    "decorative_row",
    "touching_pair",
    "stray_dot",
    "i_dot",
];

/// The ids of the O cases, in order.
pub const O_IDS: [&str; 7] = [
    "hand_pressure",
    "rough_brush",
    "ink_bleed",
    "bulb_organic",
    "stencil",
    "inline_outline",
    "complex_counters",
];

/// The id of the only S case.
pub const S_ID: &str = "specimen";

/// The ids of the cases of `level`, in a stable order, without building them.
#[must_use]
pub fn case_ids(level: Level) -> Vec<String> {
    match level {
        Level::S => vec![S_ID.to_owned()],
        Level::M => alphabet_ids("m", &M_FONTS),
        Level::MHand => alphabet_ids("mhand", &[HAND_FONT]),
        Level::L => L_IDS.iter().map(|s| (*s).to_owned()).collect(),
        Level::O => O_IDS.iter().map(|s| (*s).to_owned()).collect(),
    }
}

fn alphabet_ids(prefix: &str, fonts: &[&str]) -> Vec<String> {
    let mut ids = Vec::new();
    for font in fonts {
        for cap in M_CAPS {
            for deg in Degradation::ALL {
                ids.push(format!("{prefix}-{font}-c{cap}-{}", deg.name()));
            }
        }
    }
    ids
}

/// The level of a case id.
#[must_use]
pub fn level_of(id: &str) -> Option<Level> {
    Level::ALL
        .into_iter()
        .find(|&level| case_ids(level).iter().any(|c| c == id))
}

/// Builds one case by id.
///
/// # Errors
///
/// [`BenchError::Unknown`] for an id that is not in the corpus, or any error
/// of the generators.
pub fn build_case(id: &str) -> Result<CorpusCase, BenchError> {
    let level = level_of(id).ok_or_else(|| BenchError::Unknown(format!("case id {id:?}")))?;
    match level {
        Level::S => specimen::case(),
        Level::M | Level::MHand => render_font::alphabet_case(id, level),
        Level::L | Level::O => hard_cases::case(id, level),
    }
}

/// Builds every case of `level`. Deterministic: two calls give the same bytes.
///
/// # Errors
///
/// Any error of the generators.
pub fn corpus(level: Level) -> Result<Vec<CorpusCase>, BenchError> {
    case_ids(level).iter().map(|id| build_case(id)).collect()
}
